def longest_palindrome(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""

    best_start = 0
    best_len = 1

    d1 = [0] * n
    l = 0
    r = -1

    for i in range(n):
        if i > r:
            k = 1
        else:
            k = d1[l + r - i]
            if k > r - i + 1:
                k = r - i + 1

        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1

        d1[i] = k
        length = 2 * k - 1
        if length > best_len:
            best_len = length
            best_start = i - k + 1

        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    d2 = [0] * n
    l = 0
    r = -1

    for i in range(n):
        if i > r:
            k = 0
        else:
            k = d2[l + r - i + 1]
            if k > r - i + 1:
                k = r - i + 1

        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:
            k += 1

        d2[i] = k
        length = 2 * k
        if length > best_len:
            best_len = length
            best_start = i - k

        if i + k - 1 > r:
            l = i - k
            r = i + k - 1

    return s[best_start:best_start + best_len]
